const r = $input.first().json;
const clean = v => String(v ?? '').trim();

const reviewType = clean(
  r.review_type || 'document'
).toLowerCase();

if (!['document', 'report'].includes(reviewType)) {
  throw new Error('Invalid review_type');
}

const required = [
  'run_id',
  'snapshot_id',
  'project_name',
  'reviewer_email'
];

if (reviewType === 'document') {
  required.push(
    'document_version',
    'file_type',
    'file_id',
    'file_url'
  );
} else {
  required.push('report_content');
}

for (const field of required) {
  if (!clean(r[field])) {
    throw new Error(`Missing ${field}`);
  }
}

const reviewer = clean(r.reviewer_email).toLowerCase();

if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(reviewer)) {
  throw new Error('Invalid reviewer_email');
}

let fileType = '';
let fileUrl = '';

if (reviewType === 'document') {
  fileType = clean(r.file_type).toLowerCase();

  if (!['docx', 'pdf', 'pptx'].includes(fileType)) {
    throw new Error('Invalid file_type');
  }

  fileUrl = clean(r.file_url);

  if (!/^https:\/\/(drive|docs)\.google\.com\//i.test(fileUrl)) {
    throw new Error('Expected a Google Drive document URL');
  }
}

return [{
  json: {
    ...r,
    run_id: clean(r.run_id),
    snapshot_id: clean(r.snapshot_id),
    project_name: clean(r.project_name),
    reviewer_email: reviewer,
    review_type: reviewType,
    document_version:
      clean(r.document_version) || '1.0',
    file_type: fileType,
    file_id: clean(r.file_id),
    file_url: fileUrl,
    report_content:
      reviewType === 'report'
        ? clean(r.report_content)
        : '',
    review_id: 'REV-' + $execution.id,
    status: 'pending_review',
    requested_at: new Date().toISOString()
  }
}];

