={{ (() => {
  const r = $('Validate Review Request').first().json;
  const review = $('MIRA_Document_Reviews').first().json;

  const esc = v => String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

  const labels = {
    plan: 'Project Plan',
    risk: 'Risk Assessment',
    status: 'Status Report',
    milestone: 'Milestone Tracker',
    stakeholder_update: 'Stakeholder Update'
  };

  const capability = labels[r.capability] || 'Project Report';

  const raw = String(r.report_content || '')
    .replace(/<details>[\s\S]*?<\/details>/gi, '')
    .replace(/```json[\s\S]*?```/gi, '');

  // Extract one Markdown section without raw markup.
  const section = title => {
    const escaped = title.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = raw.match(
      new RegExp(
        '^## ' + escaped + '\\s*\\n([\\s\\S]*?)(?=^## |^---\\s*$|$)',
        'mi'
      )
    );
    return match ? match[1].trim() : '';
  };

  const plain = value => String(value || '')
    .replace(/\*\*/g, '')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/^\s*-\s+/gm, '• ')
    .trim();

  const summary =
    section('Executive Summary') ||
    (raw.match(/\*\*Summary:\*\*\s*([^\n]+)/i)?.[1] || '') ||
    section('Objectives') ||
    'See the complete stored report for details.';

  const sectionsByCapability = {
    plan: ['Objectives', 'Scope'],
    risk: ['Risk Register', 'High Priority Risks'],
    status: ['Task Progress', 'Highlights'],
    milestone: ['Upcoming Milestones', 'Milestones'],
    stakeholder_update: ['Upcoming Activities', 'Risks and Blockers']
  };

  const wanted = sectionsByCapability[r.capability] || [];

  const findings = wanted.map(title => {
    const content = section(title);
    if (!content) return '';

    const short = plain(content)
      .split('\n')
      .filter(Boolean)
      .slice(0, 5)
      .join('\n');

    return `<h4>${esc(title)}</h4>
      <p style="white-space:pre-line">${esc(short)}</p>`;
  }).filter(Boolean).join('');

  const gaps = section('Data Gaps');

  const validation = raw.match(
    /\*\*Report validation:\*\*\s*([A-Z_]+)/i
  )?.[1] || 'NOT REPORTED';

  return `
  <div style="font-family:Arial,sans-serif;
              color:#263247;max-width:700px;
              margin:auto;line-height:1.6;">

    <h2 style="color:#253d77">
      MIRA – Project Intelligence
    </h2>

    <h3>Report Review Required</h3>

    <p>An AI-generated project report is ready
    for your review.</p>

    <table style="width:100%;border-collapse:collapse;">
      <tr><td><b>Project</b></td>
          <td>${esc(r.project_name)}</td></tr>
      <tr><td><b>Capability</b></td>
          <td>${esc(capability)}</td></tr>
      <tr><td><b>Review ID</b></td>
          <td>${esc(review.review_id)}</td></tr>
      <tr><td><b>Run ID</b></td>
          <td>${esc(r.run_id)}</td></tr>
      <tr><td><b>Version</b></td>
          <td>${esc(r.document_version || '1.0')}</td></tr>
      <tr><td><b>Report Validation</b></td>
          <td>${esc(validation)}</td></tr>
      <tr><td><b>Review Status</b></td>
          <td>Pending Review</td></tr>
    </table>

    <hr style="border:0;border-top:1px solid #ddd;">

    <h3>Executive Summary</h3>
    <p style="white-space:pre-line">
      ${esc(plain(summary))}
    </p>

    ${findings}

    ${gaps ? `
      <h3>Data Limitations</h3>
      <p style="white-space:pre-line">
        ${esc(plain(gaps).split('\n').slice(0, 4).join('\n'))}
      </p>
    ` : ''}

    <hr style="border:0;border-top:1px solid #ddd;">

    <h3>Reviewer Action</h3>
    <p>Please review the complete stored draft
    before choosing Approve or Decline.
    You may enter reviewer comments in the
    review form.</p>

    <p style="font-size:12px;color:#666">
      This is an AI-generated draft. Approval applies
      only to this review ID and version and does not
      automatically authorize external distribution.
    </p>

    <p><b>MIRA – AI-Powered Project Intelligence Assistant</b></p>
  </div>`;
})() }}

