const r = $('Validate Review Request').first().json;

if (r.review_type !== 'report') {
  throw new Error(
    'PDF content preparation supports report reviews only'
  );
}

if (!r.report_content?.trim()) {
  throw new Error('Approved report content is missing');
}

// Retrieve the review record updated after approval.
const review = $('Update row(s)').first().json;

if (review.status !== 'approved') {
  throw new Error(
    'PDF generation blocked: review is not approved'
  );
}

// Preserve the exact AI-generated report.
const originalReport = String(r.report_content);

// Remove only the machine-readable JSON appendix.
// Do not modify the original stored report.
function cleanReport(value) {
  return String(value ?? '')
    .replace(/\r\n/g, '\n')

    // Remove JSON appendix inside details.
    .replace(
      /<details>[\s\S]*?<\/details>/gi,
      ''
    )

    // Remove standalone structured JSON sections.
    .replace(
      /Complete structured report data\s*```json[\s\S]*?```/gi,
      ''
    )

    // Remove remaining JSON code blocks.
    .replace(/```json[\s\S]*?```/gi, '')

    // Remove technical heading, not the report.
    .replace(
      /^#\s*MIRA PROJECT INTELLIGENCE\s*[—-]\s*DRAFT\s*$/gmi,
      ''
    )

    // Remove repeated technical execution metadata.
    .replace(
      /^\*\*(Execution|Overall validation|Snapshot|Run ID|Reports returned):\*\*.*$/gmi,
      ''
    )

    // Convert Markdown headings to plain document headings.
    .replace(
      /^#{1,6}\s+(.+)$/gm,
      (_, title) => '\n' + title.toUpperCase() + '\n'
    )

    // Remove Markdown bold markers.
    .replace(/\*\*(.*?)\*\*/g, '$1')

    // Normalize list indentation.
    .replace(/^(\s*)-\s+/gm, '$1• ')

    // Normalize excessive whitespace.
    .replace(/\n{3,}/g, '\n\n')

    .trim();
}


let formattedBody = cleanReport(originalReport);

// Remove stakeholder email draft from Status Reports only.
if (r.capability === 'status') {
  formattedBody = formattedBody.replace(
    /(?:^|\n)\s*(?:#{1,6}\s*)?STAKEHOLDER EMAIL\s*[—–-]\s*DRAFT\b[\s\S]*?(?=\n\s*(?:#{1,6}\s*)?(?:SOURCE REFERENCES|DATA GAPS|REPORT GOVERNANCE)\b|$)/i,
    '\n\n'
  );
}

// Normalize extra blank lines.
formattedBody = formattedBody
  .replace(/\n{3,}/g, '\n\n')
  .trim();


// Preserve the current review record metadata.
const reviewId = review.review_id ?? r.review_id;
const reviewerComments =
  String(review.Reviewer_Comments ?? '').trim();

const decidedAt = review.decided_at ?? '';

const capability = r.capability || 'multi';

return [{
  json: {
    review_id: reviewId,
    run_id: r.run_id,
    project_name: r.project_name,
    capability,
    reviewer_email: r.reviewer_email,
    document_version: r.document_version || '1.0',

    document_name:
      `MIRA_${capability}_${r.run_id}_APPROVED`,

    formatted_body: formattedBody,

    // Original report remains available for audit.
    original_report_content: originalReport,

    approval_status: 'APPROVED',
    reviewer_comments: reviewerComments,
    decided_at: decidedAt
  }
}];
